import os, re, glob, json, csv, io, html as htmllib

base = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_10"

def get_text(p):
    raw = open(p,'rb').read()
    return raw.decode('utf-8', errors='replace')

def parse_md(s):
    pk = re.search(r'Portfolio key\s*\|\s*([A-Z0-9\-]+)', s)
    er = re.search(r'Evidence role\s*\|\s*([a-z_]+)', s)
    ent = re.search(r'Immutable entity\s*\|\s*(ENT-\d+-\d+)', s)
    rev = re.search(r'Current revision\s*\|\s*(REV-\d+\.\d+)', s)
    ref = re.search(r'Referenced revision\s*\|\s*(REV-\d+\.\d+)', s)
    # native record = the blockquote line(s) after "> " right after control table
    # find first blockquote line
    body = None
    for m in re.finditer(r'^>\s*(.+)$', s, re.M):
        t = m.group(1).strip()
        if t and not t.startswith(('Attorney','Confidential','Restricted')):
            body = t
            break
    return (pk and pk.group(1), er and er.group(1), ent and ent.group(1), rev and rev.group(1), ref and ref.group(1), body)

def parse_txt(s):
    pk = re.search(r'PORTFOLIO KEY:\s*([A-Z0-9\-]+)', s)
    er = re.search(r'EVIDENCE ROLE:\s*([a-z_]+)', s)
    ent = re.search(r'ENTITY KEY:\s*(ENT-\d+-\d+)', s)
    rev = re.search(r'CURRENT REVISION:\s*(REV-\d+\.\d+)', s)
    ref = re.search(r'REFERENCED REVISION:\s*(REV-\d+\.\d+)', s)
    # body: text after first "NATIVE RECORD" line
    body = None
    m = re.search(r'NATIVE RECORD\n(.+?)(?:\n\n|\nSOURCE)', s, re.S)
    if m:
        body = m.group(1).strip().replace('\n',' ')
    return (pk and pk.group(1), er and er.group(1), ent and ent.group(1), rev and rev.group(1), ref and ref.group(1), body)

def parse_eml(s):
    pk = re.search(r'X-Portfolio-Key:\s*([A-Z0-9\-]+)', s)
    er = None
    # evidence role may be absent in eml; check X- headers
    m_er = re.search(r'X-Evidence-Role:\s*([a-z_]+)', s)
    er = m_er.group(1) if m_er else None
    ent = re.search(r'X-Immutable-Entity(?:-Key)?:\s*(ENT-\d+-\d+)', s)
    # body = first paragraph after the blank line following headers
    body = None
    m = re.search(r'Content-Type:.*?\n\n(.+?)(?:\n\nSOURCE|\nSOURCE)', s, re.S)
    if m:
        body = m.group(1).strip().replace('\n',' ')
    return (pk and pk.group(1), er, ent and ent.group(1), None, None, body)

def parse_csv(s):
    rows = list(csv.reader(io.StringIO(s)))
    if not rows: return (None,)*6
    header = rows[0]
    # columns: record_id,matter_number,portfolio_key,row_type,date,key,value,actor,status,reference
    pk=None; er=None; ent=None; rev=None; ref=None; body=None
    for r in rows[1:]:
        if len(r) < 8: continue
        d = dict(zip(header, r))
        if d.get('row_type')=='metadata':
            pk = pk or d.get('portfolio_key')
            k = d.get('key'); v = d.get('value')
            if k=='evidence_role': er = v
            if k=='immutable_entity_key': ent = v
            if k=='referenced_revision': ref = v
            if k=='current_revision': rev = v
            if k=='body': body = v
    return (pk, er, ent, rev, ref, body)

def parse_json(s):
    d = json.loads(s)
    return (d.get('portfolio_key'), d.get('evidence_role'), d.get('immutable_entity_key'),
            d.get('current_revision'), d.get('referenced_revision'), d.get('body'))

def parse_xml(s):
    pk = re.search(r'<portfolio-key>([A-Z0-9\-]+)</portfolio-key>', s)
    er = re.search(r'<evidence-role>([a-z_]+)</evidence-role>', s)
    ent = re.search(r'<immutable-entity-key>(ENT-\d+-\d+)</immutable-entity-key>', s)
    rev = re.search(r'<current-revision>(REV-\d+\.\d+)</current-revision>', s)
    ref = re.search(r'<referenced-revision>(REV-\d+\.\d+)</referenced-revision>', s)
    body = re.search(r'<native-record>(.+?)</native-record>', s, re.S)
    return (pk and pk.group(1), er and er.group(1), ent and ent.group(1), rev and rev.group(1), ref and ref.group(1), body and body.group(1).strip())

def parse_html(s):
    pk = re.search(r'<dt>Portfolio key</dt>\s*<dd>([A-Z0-9\-]+)</dd>', s)
    er = re.search(r'<dt>Evidence role</dt>\s*<dd>([a-z_]+)</dd>', s)
    ent = re.search(r'<dt>Entity</dt>\s*<dd>(ENT-\d+-\d+)</dd>', s)
    rev = re.search(r'<dt>Revision</dt>\s*<dd>(REV-\d+\.\d+)</dd>', s)
    body = re.search(r'<h2>Native record</h2><p>(.+?)</p>', s, re.S)
    return (pk and pk.group(1), er and er.group(1), ent and ent.group(1), rev and rev.group(1), None, body and body.group(1).strip())

def parse_pdf(p):
    # try pypdf
    try:
        from pypdf import PdfReader
        r = PdfReader(p)
        s = "\n".join((pg.extract_text() or '') for pg in r.pages)
        return s
    except Exception:
        pass
    try:
        import PyPDF2
        r = PyPDF2.PdfReader(p)
        s = "\n".join((pg.extract_text() or '') for pg in r.pages)
        return s
    except Exception as e:
        return None

files = sorted(glob.glob(base + "/**/*", recursive=True))
files = [f for f in files if os.path.isfile(f) and not f.endswith('.xlsx')]

records = {}  # (pk, role) -> dict
for f in files:
    ext = os.path.splitext(f)[1].lower()
    cat = f.split('/task_10/')[1].split('/')[0]
    if ext == '.pdf':
        s = parse_pdf(f)
        if s is None:
            continue
        # pdf text likely similar to txt layout
        r = parse_txt(s) if 'PORTFOLIO KEY' in s else parse_md(s)
    else:
        s = get_text(f)
        if ext=='.md': r = parse_md(s)
        elif ext=='.txt': r = parse_txt(s)
        elif ext=='.eml': r = parse_eml(s)
        elif ext=='.csv': r = parse_csv(s)
        elif ext=='.json': r = parse_json(s)
        elif ext=='.xml': r = parse_xml(s)
        elif ext=='.html': r = parse_html(s)
        else: r=(None,)*6
    pk, er, ent, rev, ref, body = r
    if pk and er:
        records[(pk,er)] = dict(cat=cat, file=os.path.basename(f), ext=ext, ent=ent, rev=rev, ref=ref, body=body)

# Report per key, per role
keys = sorted(set(k for (k,_) in records))
roles = ['identity_crosswalk','operative_authority','current_operations','approval_and_capacity',
         'correspondence','financial_or_population_support','chronology_and_custody','independent_counterrecord']
for k in keys:
    print("="*100)
    print("KEY", k)
    for role in roles:
        rec = records.get((k,role))
        if rec:
            body = (rec['body'] or '').replace('\n',' ')
            print(f"  [{role:32s}] rev={rec['rev']}/{rec['ref']} ent={rec['ent']} | {body[:220]}")
        else:
            print(f"  [{role:32s}] MISSING")
