import os, re, glob

base = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_10"

def pdf_text(p):
    try:
        from pypdf import PdfReader
        return "\n".join((pg.extract_text() or '') for pg in PdfReader(p).pages)
    except Exception:
        try:
            import PyPDF2
            return "\n".join((pg.extract_text() or '') for pg in PyPDF2.PdfReader(p).pages)
        except Exception as e:
            return f"PDF_FAIL: {e}"

files = sorted(glob.glob(base + "/**/*.eml", recursive=True)) + sorted(glob.glob(base + "/**/*.pdf", recursive=True))
files.sort()

# map file number -> key, role
def key_role(n):
    key = ((n-1) % 12) + 1
    ri = (n-1) // 12
    roles = ['IDE','OPE','CUR','APP','COR','FIN','CHR','IND']
    return key, roles[ri]

for f in files:
    n = int(re.search(r'(\d{3})_', os.path.basename(f)).group(1))
    key, role = key_role(n)
    if f.endswith('.eml'):
        s = open(f,'rb').read().decode('utf-8','replace')
        # portfolio key from header
        pk = re.search(r'X-Portfolio-Key:\s*([A-Z0-9\-]+)', s)
        # first body paragraph after headers
        m = re.search(r'charset=utf-8\s*\n\n(.+?)(?:\n\n|\nSOURCE)', s, re.S)
        body = m.group(1).strip().replace('\n',' ') if m else None
        print(f"[{n:03d}] key={key} role={role} | hdr_pk={pk and pk.group(1)} | {body[:260]}")
    else:
        s = pdf_text(f)
        # find portfolio key and native record
        pk = re.search(r'CBP-031-\d{2}', s)
        # native record line(s)
        m = re.search(r'NATIVE RECORD\s*\n(.+?)(?:\n\n|\nSOURCE|\nBUSINESS)', s, re.S)
        if not m:
            m = re.search(r'(?i)native record\s*(.+?)(?:source|business)', s, re.S)
        body = m.group(1).strip().replace('\n',' ') if m else s[:200].replace('\n',' ')
        print(f"[{n:03d}] key={key} role={role} | pk_in_pdf={pk and pk.group(0)} | {body[:260]}")
